class PPDefine:
    def __init__(self, name, params, variadic, value):
        self.name = name
        self.params = params  # None for object, list for function (may include '__VA_ARGS__' or '...')
        self.variadic = variadic
        self.value = value  # string

def parse_define_str(s):
    # s is like "FOO", "FOO=1", "FOO(x)=x", "FOO(x,...)=...", "FOO=bar baz"
    # Returns (name, params, variadic, value)
    # Find '=' 
    if '=' in s:
        left, val = s.split('=', 1)
    else:
        left = s
        val = "1"
    left = left.strip()
    # Check for function: name '(' ... ')'
    m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*\((.*)\)\s*$', left, re.DOTALL)
    if m:
        name = m.group(1)
        params_str = m.group(2).strip()
        if params_str == "":
            params = []
            variadic = False
        else:
            # split by comma, handling ...?
            parts = [p.strip() for p in params_str.split(',')]
            variadic = False
            params = []
            for p in parts:
                if p == "...":
                    variadic = True
                    params.append("...")
                elif p.endswith("..."):
                    # e.g., "args..." ?
                    variadic = True
                    base = p[:-3].strip()
                    if base:
                        params.append(base)
                    params.append("__VA_ARGS__")
                else:
                    params.append(p)
            # Handle __VA_ARGS__ in params?
            if "__VA_ARGS__" in params:
                variadic = True
        return name, params, variadic, val
    else:
        # object, name must be identifier? If left contains spaces? Actually -Dfoo=bar with left=foo, ok. If -D "foo bar"? Unlikely.
        name = left
        return name, None, False, val

def find_include_file(name, is_system, cur_dir, ipaths, isystem_paths, nostdinc, install):
    # Search order:
    # For "": first cur_dir, then ipaths, then isystem, then standard (if not nostdinc)
    # For <>: first ipaths? Actually for <> , cur_dir not searched? Standard: "" searches cur_dir first, <> doesn't.
    # Need to determine: tcc search order: current dir for "", then -I, then -isystem, then standard?
    # Standard paths: install/include, /usr/local/include/x86_64-linux-gnu, /usr/local/include, /usr/include/x86_64-linux-gnu, /usr/include
    # isystem paths are system (for -MM exclusion)
    # ipaths are user (for -MM inclusion)
    # Returns (fullpath, is_system_flag)
    std_paths = []
    if not nostdinc:
        std_paths = [install + "/include",
                     "/usr/local/include/x86_64-linux-gnu",
                     "/usr/local/include",
                     "/usr/include/x86_64-linux-gnu",
                     "/usr/include"]
    if not is_system:
        # ""
        if cur_dir and cur_dir != "":
            p = os.path.join(cur_dir, name)
            if os.path.isfile(p):
                return p, False
        for d in ipaths:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                return p, False
        for d in isystem_paths:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                return p, True
        for d in std_paths:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                # standard is system? For -MM, standard headers are system (excluded). Yes.
                return p, True
        return None, False
    else:
        # <>
        for d in ipaths:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                return p, False
        for d in isystem_paths:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                return p, True
        for d in std_paths:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                return p, True
        return None, False

PYEOF
echo OK
